/// <summary>
/// Runs the class with the specified arguments.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    KCS_GAEBPos gaebPos;

    while select forupdate gaebPos where !gaebPos.LfdNrInt
    {
        ttsbegin;
        gaebPos.LfdNrInt = str2Int(gaebPos.LfdNr);
        gaebPos.update();
        ttscommit;
    }
}
